window.MG_LAZY_DATA["data/lazy/resources/security-v26-098-5ee2c7cfd21b7b7e.json"]={sha256:"5ee2c7cfd21b7b7e126721d3f2961dbdd902779d90d9f5e067a1ca9ad9c59cd8",value:{"sources":[{"id":"v26-case-f561a6295e1b6a09","url":"https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final","title":"NIST SP 800-34r1 contingency planning","titleEn":"NIST SP 800-34r1 contingency planning","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-098","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-098","related":[{"id":"security-v26-099","referenceUrls":["https://sre.google/sre-book/postmortem-culture/"],"title":"Google SRE Postmortem：可驗證改善與無責備學習","titleEn":"Google SRE postmortems: verifiable improvements and blameless learning","why":"用兩課的可觀察驗收條件比較模型邊界：交付BIA假設、RTO/RPO表、交易標記、85分鐘復原演練及裕度改善建議。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver BIA assumptions, RTO/RPO table, transaction markers, eighty-five-minute drill and margin improvements.","difference":"區分觸發、促成條件、偵測缺口與恢復因素，讓每項行動有擁有者、期限及驗證方法。","differenceEn":"Separate trigger, contributing conditions, detection gaps and recovery factors; assign each action an owner, deadline and verification method.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["最壞資料時間損失可用成功備份間隔作簡化上界，但必須考慮備份失敗；RTO另含還原與驗證。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 目標RPO15分鐘、RTO90分鐘；本簡化模型假設中斷立即被偵測並宣告，無額外等待。備份每10分鐘成功一次，還原50分鐘、驗證25分鐘、切換10分鐘。 理想RPO上界10分鐘符合15；復原總85分鐘，距RTO剩5分鐘裕度。","有效完成率=已有驗證證據的改善行動/已承諾行動；工單關閉不等於控制有效。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 事後檢討承諾12項行動，9張工單已關閉，但只有7項有可重跑驗證。 工單關閉率75%，有效完成率7/12=58.3333%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A successful backup interval can approximate a worst-case data-time loss bound, but failures matter; RTO separately includes restore and validation. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Targets are RPO fifteen minutes and RTO ninety minutes; this simplified model assumes immediate detection and declaration at disruption, with no extra waiting. Successful backups occur every ten minutes, with fifty-minute restore, twenty-five-minute validation and ten-minute cutover. Ideal RPO bound is ten minutes, meeting fifteen; recovery totals eighty-five minutes with five minutes of RTO margin.","Effective completion is verified improvements divided by committed actions; a closed ticket does not prove effectiveness. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A postmortem commits to twelve actions; nine tickets are closed, but only seven have repeatable validation. Ticket closure is 75%, but effective completion is 58.3333%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-008","referenceUrls":["https://web.mit.edu/kerberos/krb5-latest/doc/admin/index.html"],"title":"MIT Kerberos：票證、主體與時鐘邊界","titleEn":"MIT Kerberos: tickets, principals and clock boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：交付BIA假設、RTO/RPO表、交易標記、85分鐘復原演練及裕度改善建議。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver BIA assumptions, RTO/RPO table, transaction markers, eighty-five-minute drill and margin improvements.","difference":"畫出測試realm的使用者、TGT、服務票證與服務主體；將票證有效期、可更新期限、時鐘偏差分開，不展示keytab內容。","differenceEn":"Map a test realm user, TGT, service ticket and service principal; separate validity, renewable lifetime and clock skew without exposing keytab contents.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["最壞資料時間損失可用成功備份間隔作簡化上界，但必須考慮備份失敗；RTO另含還原與驗證。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 目標RPO15分鐘、RTO90分鐘；本簡化模型假設中斷立即被偵測並宣告，無額外等待。備份每10分鐘成功一次，還原50分鐘、驗證25分鐘、切換10分鐘。 理想RPO上界10分鐘符合15；復原總85分鐘，距RTO剩5分鐘裕度。","剩餘有效期=endtime−now，不能用renew-till代替endtime；票證可更新不代表過期票證仍能直接使用。 合成服務票證endtime=7200秒、now=3600秒、renew-till=14400秒。 可用餘裕7200−3600=3600秒；將endtime縮為5400秒後餘裕1800秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["A successful backup interval can approximate a worst-case data-time loss bound, but failures matter; RTO separately includes restore and validation. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Targets are RPO fifteen minutes and RTO ninety minutes; this simplified model assumes immediate detection and declaration at disruption, with no extra waiting. Successful backups occur every ten minutes, with fifty-minute restore, twenty-five-minute validation and ten-minute cutover. Ideal RPO bound is ten minutes, meeting fifteen; recovery totals eighty-five minutes with five minutes of RTO margin.","Remaining validity is endtime−now, not renew-till−now; renewable tickets are not automatically usable after expiry. A synthetic service ticket has endtime=7200 seconds, now=3600 and renew-till=14400. Margin is 7200−3600=3600 seconds; shortening endtime to 5400 leaves 1800 seconds.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-571b75f6e0d45b7e","url":"https://sre.google/sre-book/postmortem-culture/","title":"Google SRE: postmortem culture","titleEn":"Google SRE: postmortem culture","publisher":"Google SRE","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-8bc872e7fad6bddd","url":"https://web.mit.edu/kerberos/krb5-latest/doc/admin/index.html","title":"MIT Kerberos: For administrators","titleEn":"MIT Kerberos: For administrators","publisher":"MIT","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
